import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Element_equals_TriageGen0Test {

    @Test
    public void testEquals_SelfReference_ReturnsTrue() {
        Element element = new Element(Tag.valueOf("div"), "");
        assertTrue(element.equals(element));
    }

    @Test
    public void testEquals_Null_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(null));
    }

    @Test
    public void testEquals_DifferentClass_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(new Object()));
    }

    @Test
    public void testEquals_Superclass_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(new Object()));
    }

    @Test
    public void testEquals_SameObject_ReturnsTrue() {
        Element element = new Element(Tag.valueOf("div"), "");
        Element sameElement = element;
        assertTrue(element.equals(sameElement));
    }

    @Test
    public void testEquals_SameClassDifferentAttributes_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        Element sameClassDifferentAttributes = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(sameClassDifferentAttributes));
    }

    @Test
    public void testEquals_SameClassSameAttributesDifferentText_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        Element sameClassSameAttributesDifferentText = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(sameClassSameAttributesDifferentText));
    }

    @Test
    public void testEquals_SameClassSameAttributesSameTextDifferentChildren_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        Element sameClassSameAttributesSameTextDifferentChildren = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(sameClassSameAttributesSameTextDifferentChildren));
    }

    @Test
    public void testEquals_SameClassSameAttributesSameTextSameChildrenDifferentParent_ReturnsFalse() {
        Element element = new Element(Tag.valueOf("div"), "");
        Element sameClassSameAttributesSameTextSameChildrenDifferentParent = new Element(Tag.valueOf("div"), "");
        assertFalse(element.equals(sameClassSameAttributesSameTextSameChildrenDifferentParent));
    }
}
